def populate_project_slugs(apps, schema_editor):
    Project = apps.get_model('projects', 'Project')
    database = schema_editor.connection.alias

    for project in Project.objects.using(database).order_by('pk').iterator():
        transliterated = ''.join(
            UKRAINIAN_TRANSLIT.get(character, character)
            for character in project.project_title.lower()
        )
        base_slug = slugify(transliterated) or 'project'
        base_slug = base_slug[:255].rstrip('-') or 'project'
        unique_slug = base_slug
        counter = 1

        while (
            Project.objects.using(database)
            .filter(slug=unique_slug)
            .exclude(pk=project.pk)
            .exists()
        ):
            suffix = f'-{counter}'
            unique_slug = (
                f'{base_slug[:255 - len(suffix)].rstrip("-")}{suffix}'
            )
            counter += 1

        project.slug = unique_slug
        project.save(using=database, update_fields=['slug'])


def clear_project_slugs(apps, schema_editor):
    Project = apps.get_model('projects', 'Project')
    Project.objects.using(schema_editor.connection.alias).update(slug=None)


